const userMeetings = `-- name: UserMeetings :many
SELECT m.id, m.title, m.starts_at, m.ends_at, m.timezone, m.rrule, m.cancelled_at, i.response,
    (m.organizer_id = $1)::boolean AS organizer
FROM meeting_invitees i JOIN meetings m ON m.id = i.meeting_id
WHERE i.user_id = $1
ORDER BY m.starts_at
`

type UserMeetingsRow struct {
	ID          pgtype.UUID        `json:"id"`
	Title       string             `json:"title"`
	StartsAt    time.Time          `json:"starts_at"`
	EndsAt      time.Time          `json:"ends_at"`
	Timezone    string             `json:"timezone"`
	Rrule       string             `json:"rrule"`
	CancelledAt pgtype.Timestamptz `json:"cancelled_at"`
	Response    string             `json:"response"`
	Organizer   bool               `json:"organizer"`
}

// A person's meetings for their data export.
func (q *Queries) UserMeetings(ctx context.Context, userID pgtype.UUID) ([]UserMeetingsRow, error) {
	rows, err := q.db.Query(ctx, userMeetings, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserMeetingsRow
	for rows.Next() {
		var i UserMeetingsRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.StartsAt,
			&i.EndsAt,
			&i.Timezone,
			&i.Rrule,
			&i.CancelledAt,
			&i.Response,
			&i.Organizer,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
